#!/usr/bin/env bash
# Builds the self-contained demo pages (one HTML file each, no dependencies
# but Google Fonts) from these sources. Run from anywhere:
#   bash docs/design/redesign/src/build.sh
# Edit the sources, not the generated demo-*.html files.
set -euo pipefail
cd "$(dirname "$0")"
OUT=..

build() { # $1 = demo id (h|i|j), $2 = output file, $3 = title
  {
    cat <<HEAD
<!doctype html>
<!-- Generated by docs/design/redesign/src/build.sh from src/ — edit the sources, not this file. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>$3</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
HEAD
    cat base.css "$1.css"
    printf '</style>\n</head>\n<body>\n<script>\n'
    cat data.js core-infra.js core-model.js core-pages.js core-rules.js h-rules.js h-extras.js "$1.js"
    printf '</script>\n</body>\n</html>\n'
  } > "$OUT/$2"
  echo "built $2 ($(wc -c < "$OUT/$2") bytes)"
}

build h demo-h-guided.html "Demo H: Guided"
